import type { MenuItemProps } from "./menu-item/menu-item.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixDropdownMenu from "@radix-ui/react-dropdown-menu";

import { useMenu } from "../hooks/use-menu";
import { MenuClasses } from "../menu.styles";

import { StyledMenuItem, MenuItemClasses } from "./menu-item/menu-item.styles";
import { MenuGroup } from "./menu-group";
import { MenuDivider } from "./menu-divider";

const MenuSub = ({
  children,
  ...props
}: React.ComponentPropsWithoutRef<typeof RadixDropdownMenu.Sub>) => {
  const { RadixComponent } = useMenu();
  return <RadixComponent.Sub {...props}>{children}</RadixComponent.Sub>;
};
MenuSub.displayName = "Menu.Sub";

const MenuSubTrigger = forwardRef<HTMLDivElement, MenuItemProps>(
  (
    { children, className, variant: variantProp, styleSlots, style, size: sizeProp, ...props },
    ref,
  ) => {
    const { RadixComponent, variant, size: contextSize } = useMenu();
    const theme = useTheme();
    const size = sizeProp || contextSize;
    const menuItemClasses = clsx(
      MenuItemClasses.root,
      {
        [MenuItemClasses.sm]: size === "sm",
      },
      className,
    );

    return (
      <RadixComponent.SubTrigger ref={ref} asChild {...props}>
        <StyledMenuItem
          className={menuItemClasses}
          currentTheme={theme}
          style={style}
          styleSlots={styleSlots}
          variant={variantProp || variant}
        >
          {children}
        </StyledMenuItem>
      </RadixComponent.SubTrigger>
    );
  },
);
MenuSubTrigger.displayName = "Menu.SubTrigger";

const MenuSubContent = forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ children, className, ...props }, ref) => {
    const { loop, RadixComponent } = useMenu();

    const childrenArray = React.Children.toArray(children);
    const groupedChildren: React.ReactNode[] = [];
    let currentGroup: React.ReactNode[] = [];

    const isGroup = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName === MenuGroup.displayName;

    const isDivider = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName === MenuDivider.displayName;

    const flushGroup = () => {
      if (currentGroup.length > 0) {
        groupedChildren.push(<MenuGroup key={groupedChildren.length}>{currentGroup}</MenuGroup>);
        currentGroup = [];
      }
    };

    childrenArray.forEach((child) => {
      if (isGroup(child) || isDivider(child)) {
        flushGroup();
        groupedChildren.push(child);
      } else {
        currentGroup.push(child);
      }
    });

    flushGroup();

    return (
      <RadixComponent.SubContent
        ref={ref}
        className={clsx(MenuClasses.content, MenuClasses.subContent, className)}
        loop={loop}
        sideOffset={14}
        {...props}
      >
        {groupedChildren}
      </RadixComponent.SubContent>
    );
  },
);
MenuSubContent.displayName = "Menu.SubContent";

export { MenuSub, MenuSubTrigger, MenuSubContent };
